B.a_o=new A.d6([B.ch,"Waarom heet het trappist?",'Een bier mag het logo "Authentic Trappist Product" alleen dragen als het onder toezicht van monniken binnen een trappistenabdij wordt gebrouwen.',null,null,null])
B.a_G=new A.d6([B.cg,"Amber Kompas IPA","Fris bitter met grapefruit en dennen, maar de moutbasis houdt alles mooi in balans. Een perfect terrasbier.",null,"Joris",4])
B.a_q=new A.d6([B.cz,"Schenk schuin, eindig recht","Houd het glas schuin tijdens het inschenken en zet het halverwege rechtop. Zo krijg je een kraag van ongeveer twee vingers.",null,"BierKompas",null])
B.a_w=new A.d6([B.ch,"Bock komt uit Einbeck","De naam bockbier is waarschijnlijk een verbastering van Einbeck, een Duitse stad die in de middeleeuwen bekend was om zijn sterke bier.",null,null,null])
B.a_x=new A.d6([B.cg,"Donkere Molen Stout","Koffie, pure chocolade en een fluweelzachte mondvulling. Laat hem iets opwarmen, dan komt de vanille los.",null,"Fatima",4.5])
B.a_O=new A.d6([B.cz,"Niet elk bier hoort ijskoud","Pils smaakt het best rond 3 tot 5 graden, maar dubbels, tripels en stouts komen pas echt tot hun recht rond 8 tot 12 graden.",null,"BierKompas",null])
B.a_N=new A.d6([B.ch,"Hop is familie van hennep","Hop en hennep horen allebei bij de plantenfamilie Cannabaceae. Hop geeft bier bitterheid, aroma en een langere houdbaarheid.",null,null,null])
