B.a_C=new A.d6([B.cz,"Bewaar flessen rechtop","Rechtop, koel en donker bewaard blijft bier langer goed. Licht kan zorgen voor een onaangename, muffe smaak.",null,"BierKompas",null])
B.a_y=new A.d6([B.ch,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
